var registers = msg.payload.data;
var output = {};

// Tank level sensor (holding register 100)
output.tank_level = (registers[0] * 0.1).toFixed(1);

// Pump A status (holding register 101)
output.pump_a = registers[1] === 1 ? "RUNNING" : "STOPPED";

// Pump B status (holding register 102)
output.pump_b = registers[2] === 1 ? "RUNNING" : "STOPPED";

// Process temperature (holding register 103, scaled x0.01)
output.temperature = (registers[3] * 0.01).toFixed(2);

// Valve position 0-100% (holding register 104)
output.valve_pos = registers[4];

msg.payload = output;
msg.topic = "plc/tank";
return msg;
